import re
from pathlib import Path
TOKEN=re.compile(r'`((?:pages|samples)/[^`\s:]+):(\d+)(?:-(\d+))?`')
for name in ['19-remote-api-and-service.md','20-machine-macos-windows.md','21-logging-and-events.md','22-healthchecks-and-telemetry.md','23-troubleshooting-and-maintenance.md']:
    lines=Path(name).read_text().splitlines(); problems=[]; open_=False
    for i,l in enumerate(lines):
        if not l.startswith('```'): continue
        if not open_:
            head=lines[i-1] if i else ''
            lang=l[3:].strip()
            tok=TOKEN.findall(head); derived=bool(re.search(r'\bderived\b',head,re.I))
            if (tok or not derived) or not lang: problems.append(f'open@{i+1} head={head!r} lang={lang!r}')
            open_=True
        else:
            open_=False
    if open_: problems.append('unclosed fence')
    print(name, 'OK' if not problems else problems)
PY)
