import re
from pathlib import Path
TOKEN=re.compile(r'`((?:pages|samples)/[^`\s:]+):(\d+)(?:-(\d+))?`')
URL=re.compile(r'https?://[^\s)`]+')
files=['19-remote-api-and-service.md','20-machine-macos-windows.md','21-logging-and-events.md','22-healthchecks-and-telemetry.md','23-troubleshooting-and-maintenance.md']
for name in files:
    t=Path(name).read_text(); lines=t.splitlines(); problems=[]
    heads=[l for l in lines if l.startswith('## ')]
    if not re.match(r'^# \d\d — \S',lines[0]): problems.append('bad first line')
    if len(heads)<3 or heads[-2:]!=['## Pitfalls','## Sources']: problems.append(f'bad heads {heads[-2:]}')
    if not (URL.search(t[t.find('## Sources'):]) or '`pages/' in t[t.find('## Sources'):]): problems.append('no sources')
    for path,a,b in TOKEN.findall(t):
        p=Path(path); n=len(p.read_text().splitlines()) if p.is_file() else -1
        if n<0 or int(a)<1 or int(b or a)>n: problems.append(f'bad token {path}:{a}-{b} n={n}')
    open_=False
    for i,l in enumerate(lines):
        if not l.startswith('```'): continue
        if not open_:
            head=lines[i-1] if i else ''
            if not (l[3:].strip() and (TOKEN.findall(head) or re.search(r'\bderived\b',head,re.I) or URL.search(head))):
                problems.append(f'bad fence head@{i+1}: {head!r}')
            if TOKEN.findall(head):
                lo,hi=int(TOKEN.findall(head)[0][1]),int(TOKEN.findall(head)[0][2] or TOKEN.findall(head)[0][1])
                want=[x.rstrip() for x in Path(TOKEN.findall(head)[0][0]).read_text().splitlines()[lo-1:hi] if x.strip()!='…']
                j=i+1; body=[]
                while j<len(lines) and not lines[j].startswith('```'): body.append(lines[j]); j+=1
                got=[x.rstrip() for x in body if x.strip()!='…']
                if want!=got: problems.append(f'nonverbatim fence@{i+1}')
            open_=True
        else: open_=False
    if open_: problems.append('unclosed fence')
    for bad in ('TBD','TODO','PLACEHOLDER','unverified claim'):
        if bad in t: problems.append('placeholder '+bad)
    print(f'{name}: {len(lines)} lines, {len(TOKEN.findall(t))} citations ->', 'OK' if not problems else problems)
PY)
